  // ---- camera --------------------------------------------------------------
  // lookAt builds a view transform (world -> camera space).
  function makeCamera(eye, target, up) {
    var f = v3norm(v3sub(target, eye));       // forward
    var r = v3norm(v3cross(f, up));           // right
    var u = v3cross(r, f);                    // true up
    return {
