      forward: f,
      right: r,
      up: u,
      // Transform a world point into camera space.
      toCamera: function (p) {
        var d = v3sub(p, eye);
        return vec3(v3dot(d, r), v3dot(d, u), v3dot(d, f));
      }
    };
  }

  // ---- perspective projection ----------------------------------------------
